+#define PNAME  "SAE J2735 Message"
+#define PSNAME "J2735"
+#define PFNAME "j2735"
+
+void proto_register_j2735(void);
+void proto_reg_handoff_j2735(void);
+
+static dissector_handle_t j2735_handle;
+
+/* PSID range to be passed to SAE J2735 dissector */
+static range_t *global_psid_list;
+/* This is used for PSID range */
+#define DEFAULT_PSID_RANGE "32,39,128,129,130,131,132,133,142,143,144,145,2113685,2113686,2113687,2113689"
+#define MAX_PSID        4294967295
+
+#if defined(__GNUC__)
+/*
+ *
+ * DIAG_OFF doesn't work with llvm-gcc, for some unknown reason, so
+ * we just use the pragma directly.
+ */
+#pragma GCC diagnostic ignored "-Wunused-function"
+#endif
+
+/* Initialize the protocol and registered fields */
+int proto_j2735 = -1;
+#include "packet-j2735-hf.c"
+
+/* Initialize the subtree pointers */
+static int ett_j2735 = -1;
+#include "packet-j2735-ett.c"
+
+/* Global variables */
+static uint32_t DSRCmsgID;
+static uint32_t PartII_Id;
+static uint32_t CCM_PartII_Id;
+
+static dissector_table_t dsrcmsgid_dissector_table;
+static dissector_table_t j2735_partii_id_dissector_table;
+static dissector_table_t j2735_ccm_partii_id_dissector_table;
+
+#include "packet-j2735-val.h"
+
+static int dissect_j2735_DSRCmsgID_msg(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    return (dissector_try_uint_with_data(dsrcmsgid_dissector_table, DSRCmsgID, tvb, pinfo, tree, false, NULL)) ? tvb_captured_length(tvb) : 0;
+}
+
+static int dissect_j2735_partii_value(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    return (dissector_try_uint_with_data(j2735_partii_id_dissector_table, PartII_Id, tvb, pinfo, tree, false, NULL)) ? tvb_captured_length(tvb) : 0;
+}
+
+static int dissect_j2735_ccm_partii_value(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    return (dissector_try_uint_with_data(j2735_ccm_partii_id_dissector_table, CCM_PartII_Id, tvb, pinfo, tree, false, NULL)) ? tvb_captured_length(tvb) : 0;
+}
+
+#include "packet-j2735-fn.c"
+
+
+static int
+dissect_j2735(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void* data _U_)
+{
+    proto_item *j2735_item = NULL;
+    proto_tree *j2735_tree = NULL;
+
+    int offset = -1;
+
+
+    col_set_str(pinfo->cinfo, COL_PROTOCOL, "SAE J2735");
+
+    proto_tree* root_tree = proto_tree_get_root(tree);
+
+    j2735_item = proto_tree_add_item(root_tree, proto_j2735, tvb, 0, -1, ENC_NA);
+    j2735_tree = proto_item_add_subtree(j2735_item, ett_j2735);
+
+    offset = dissect_MessageFrame_PDU(tvb, pinfo, j2735_tree, data);
+
+    return offset;
+}
+
+/*--- proto_register_j2735 ----------------------------------------------*/
+
+void proto_register_j2735(void) {
+
+  /* List of fields */
+  static hf_register_info hf[] = {
+#include "packet-j2735-hfarr.c"
+  };
+
+  /* List of subtrees */
+  static int *ett[] = {
+      &ett_j2735,
+#include "packet-j2735-ettarr.c"
+  };
+
+  /* Register protocol */
+  proto_j2735 = proto_register_protocol(PNAME, PSNAME, PFNAME);
+
+  /* Register fields and subtrees */
+  proto_register_field_array(proto_j2735, hf, array_length(hf));
+  proto_register_subtree_array(ett, array_length(ett));
+
+  j2735_handle = register_dissector("j2735", dissect_j2735, proto_j2735);
+
+  dsrcmsgid_dissector_table = register_dissector_table("j2735.msg",
+                                                       "J2735 message dissector table",
+                                                       proto_j2735,
+                                                       FT_UINT32,
+                                                       BASE_DEC);
+  j2735_partii_id_dissector_table = register_dissector_table("j2735.partii-id",
+                                                             "J2735 PARTII-EXT-ID table",
+                                                             proto_j2735,
+                                                             FT_UINT32,
+                                                             BASE_DEC);
+  j2735_ccm_partii_id_dissector_table = register_dissector_table("j2735.ccm-partii-id",
+                                                                 "J2735 CCM PARTII-EXT-ID table",
+                                                                 proto_j2735,
+                                                                 FT_UINT32,
+                                                                 BASE_DEC);
+
+    range_convert_str(wmem_epan_scope(),
+                      &global_psid_list,
+                      DEFAULT_PSID_RANGE,
+                      MAX_PSID);
+
+    module_t* j2735_module = prefs_register_protocol(proto_j2735, proto_reg_handoff_j2735);
+
+    prefs_register_range_preference(j2735_module,
+                                    "ieee1609dot2.psid",
+                                    "PSIDs",
+                                    "PSIDs to be decoded as SAE J2735 data (default: "
+                                    DEFAULT_PSID_RANGE ")",
+                                    &global_psid_list,
+                                    MAX_PSID);
+}
+
+
+/*--- proto_reg_handoff_j2735 -------------------------------------------*/
+void proto_reg_handoff_j2735(void) {
+
+    static bool inited = false;
+    static range_t* current_psid_list = NULL;
+
+#include "packet-j2735-dis-tab.c"
+
+
+    if(!inited) {
+        inited = true;
+    } else {
+        dissector_delete_uint_range("ieee1609dot2.psid", current_psid_list, j2735_handle);
+        wmem_free(wmem_epan_scope(), current_psid_list);
+    }
+
+    current_psid_list = range_copy(wmem_epan_scope(), global_psid_list);
+    dissector_add_uint_range("ieee1609dot2.psid", current_psid_list, j2735_handle);
+}
